package EVThermalManagementSystemModel {
    private import ScalarValues::*;
    private import ISQ::*;
    private import SI::*;

    // ===== 1. 端口定义 =====
    port def CoolantPort {
        out attribute flowRate :> ISQ::volumeFlowRate;
        out attribute temperature :> ISQ::thermodynamicTemperature;
    }

    port def RefrigerantPort {
        out attribute massFlowRate :> ISQ::massFlowRate;
        out attribute pressure :> ISQ::pressure;
    }

    port def ThermalControlPort {
        in attribute enableCommand : Boolean;
        in attribute targetTemperature :> ISQ::thermodynamicTemperature;
    }

    port def HeatExchangePort {
        out attribute heatFlow :> ISQ::power;
    }

    // ===== 2. 部件定义（子系统类型） =====
    part def BatteryThermalManagement {
        doc /* 电池热管理子系统：直接服务电池冷却、预热和均温的调温子系统。 */
        attribute targetTemperature :> ISQ::thermodynamicTemperature;
        attribute upperTemperatureLimit :> ISQ::thermodynamicTemperature;
        attribute allowedTemperatureSpread :> ISQ::thermodynamicTemperature;
        port coolantIn : CoolantPort;
        port coolantOut : CoolantPort;
        port controlIn : ThermalControlPort;
        port batteryThermalPort : HeatExchangePort;
    }

    part def CabinThermalManagement {
        doc /* 座舱热管理子系统：调节乘员舱温度与送风的调温子系统。 */
        attribute cabinSetTemperature :> ISQ::thermodynamicTemperature;
        port coolantIn : CoolantPort;
        port coolantOut : CoolantPort;
        port controlIn : ThermalControlPort;
        port cabinAirPort : HeatExchangePort;
    }

    part def ThermalLoop {
        doc /* 热回路子系统：承载冷却液输运与热量输配的液体回路。 */
        attribute coolantFlowRate :> ISQ::volumeFlowRate;
        port coolantIn : CoolantPort;
        port coolantOut : CoolantPort;
        port refrigerantIn : RefrigerantPort;
        port refrigerantOut : RefrigerantPort;
    }

    part def HeatPumpAssembly {
        doc /* 热泵组件：通过制冷剂循环实现制热与制冷的组件。 */
        attribute heatingCapacity :> ISQ::power;
        attribute coefficientOfPerformance : Real;
        port refrigerantIn : RefrigerantPort;
        port refrigerantOut : RefrigerantPort;
        port controlIn : ThermalControlPort;
    }

    // ===== 3. 系统顶层结构 =====
    part def EVThermalManagementSystem {
        doc /* 纯电动汽车热管理系统：通过冷却液、制冷剂及热接口调节电池与座舱温度的系统对象。 */
        attribute designHeatLoad :> ISQ::power;
        attribute maximumAuxPower :> ISQ::power;
        port coolantBus : CoolantPort;
        port refrigerantBus : RefrigerantPort;
        port thermalCommand : ThermalControlPort;

        part batteryThermalManagement : BatteryThermalManagement;
        part cabinThermalManagement : CabinThermalManagement;
        part thermalLoop : ThermalLoop;
        part heatPumpAssembly : HeatPumpAssembly;
    }

    // ===== 4. 需求定义 =====
    requirement def ReqEndurance {
        doc /* 续航需求：整车在标准工况下的续驶里程不低于 500 km。 */
        subject tms : EVThermalManagementSystem;
        attribute requiredRange :> ISQ::length;
        attribute actualRange :> ISQ::length;
        require constraint { actualRange >= requiredRange }
    }

    requirement def ReqColdStart {
        doc /* 低温启动需求：低温环境下热管理系统须支持电池与座舱的启动加热。 */
        subject tms : EVThermalManagementSystem;
        attribute coldStartAmbientTemperature :> ISQ::thermodynamicTemperature;
        attribute coldStartDuration :> ISQ::duration;
    }

    // ===== 5. 需求使用与满足分配 =====
    requirement reqEndurance : ReqEndurance;
    requirement reqColdStart : ReqColdStart;

    part evThermalManagementSystem : EVThermalManagementSystem;

    satisfy reqEndurance by evThermalManagementSystem;
    satisfy reqColdStart by evThermalManagementSystem;
}

```

