        part def '操作员';
        // PLACEHOLDER: 占位主体类型，待结构视图建立真实 '外部监视平台' 后删除本 def 并改引其限定名
        part def '外部监视平台';

        package '任务需求' {
            doc /* 任务需求层：系统级任务能力要求 */

            requirement <'MR-1'> '目标搜索与航迹形成' {
                doc /* 支持对指定类别低空目标搜索、发现并形成稳定航迹 */
                text = """在规定任务场景和参考条件下，低空预警雷达系统应支持对指定类别的低空空中目标进行搜索、发现，并在满足航迹起始条件后形成和持续维护稳定航迹。""";
                subject '系统' : '雷达系统';
                stakeholder '操作员' : '操作员';
            }

            requirement <'MR-2'> '连续监视与模式切换' {
                doc /* 在规定区域及时段内连续执行监视并支持模式切换 */
                text = """系统应在规定监视区域及任务时段内连续执行低空空情监视，并支持按任务需要进行监视模式切换。""";
                subject '系统' : '雷达系统';
                stakeholder '操作员' : '操作员';
            }

            requirement <'MR-3'> '航迹信息输出' {
                doc /* 向外部监视平台提供目标航迹信息 */
                text = """系统应向约定的外部监视平台提供可供后续监视和预警业务使用的目标航迹信息。""";
                subject '系统' : '雷达系统';
                stakeholder '外部平台' : '外部监视平台';
            }

            requirement <'MR-4'> '任务控制与状态反馈' {
                doc /* 操作员可发起任务、调整模式、查看状态并获得反馈 */
                text = """操作员应能够向雷达系统发起低空监视任务，按任务需要进行监视模式调整、查看任务执行状态，并在任务完成或需要中止时下达停止指令，获得相应任务状态反馈。""";
                subject '系统' : '雷达系统';
                stakeholder '操作员' : '操作员';
            }

            requirement <'MR-5'> '运行状态与健康监控' {
                doc /* 提供运行状态、健康状态及故障信息支持维护保障 */
                text = """系统应在执行低空监视任务期间提供必要的运行状态、健康状态以及故障或降级信息，支持操作员监视、维护保障人员处置，并按约定接口向外部监视平台提供系统健康状态。""";
                subject '系统' : '雷达系统';
                stakeholder '操作员' : '操作员';
                stakeholder '外部平台' : '外部监视平台';
                attribute '健康状态监测周期' :> ISQ::duration;
                attribute '健康状态上报时延' :> ISQ::duration;
                require constraint { '健康状态监测周期' <= 5.0 * SI::s }
                require constraint { '健康状态上报时延' <= 3.0 * SI::s }
            }
        }

        package '系统需求' {
            doc /* 系统需求层：系统功能与接口要求 */

            requirement <'SR-1'> '目标搜索与检测' {
                doc /* 根据监视区域、目标类别及模式执行目标搜索和检测 */
                text = """系统应根据规定的监视区域、目标类别及监视模式执行空中目标搜索和发现，形成可供后续处理使用的目标检测结果。""";
                subject '系统' : '雷达系统';
                stakeholder '操作员' : '操作员';
                deriveFrom <'MR-1'>;
            }

            requirement <'SR-2'> '航迹建立与维护' {
                doc /* 依据检测结果建立目标航迹并持续关联更新维护 */
                text = """系统应依据目标检测结果，在满足航迹起始条件后建立目标航迹，并在持续监视过程中对航迹进行关联、更新和维护。""";
                subject '系统' : '雷达系统';
                stakeholder '操作员' : '操作员';
                deriveFrom <'MR-1'>;
            }

            requirement <'SR-3'> '航迹信息输出' {
                doc /* 按约定格式和时效通过接口输出目标航迹信息 */
                text = """系统应按约定格式和时效要求，通过对外接口向外部监视平台输出已形成并维护的目标航迹信息。""";
                subject '系统' : '雷达系统';
                stakeholder '外部平台' : '外部监视平台';
                deriveFrom <'MR-3'>;
                attribute '航迹输出时延' :> ISQ::duration;
                require constraint { '航迹输出时延' <= 1.5 * SI::s }
            }

            requirement <'SR-4'> '持续监视运行' {
                doc /* 在规定区域和时段内持续执行观测数据处理 */
                text = """系统应在规定监视区域和任务时段内持续执行观测数据获取、目标检测及航迹处理，并支持监视任务的持续运行。""";
                subject '系统' : '雷达系统';
                stakeholder '操作员' : '操作员';
                deriveFrom <'MR-2'>;
                attribute '连续运行可用度' : Real;
                require constraint { '连续运行可用度' >= 0.95 }
            }

            requirement <'SR-5'> '健康状态监测' {
                doc /* 监测关键分系统运行状态并识别故障或降级信息 */
                text = """系统应监测关键分系统的运行状态，识别必要的故障或降级状态信息，为运行状态查看、健康状态上报和维护保障提供依据。""";
                subject '系统' : '雷达系统';
                stakeholder '操作员' : '操作员';
                deriveFrom <'MR-2'>;
                deriveFrom <'MR-5'>;
                attribute '健康状态监测周期' :> ISQ::duration;
                require constraint { '健康状态监测周期' <= 5.0 * SI::s }
            }

            requirement <'SR-6'> '任务启停控制' {
                doc /* 接收任务启停指令并组织单元启动或结束任务 */
                text = """系统应接收操作员下达的有效监视任务启动和停止指令，组织相关单元启动或结束当前监视任务，并向操作员反馈任务启动、执行或停止状态。""";
                subject '系统' : '雷达系统';
                stakeholder '操作员' : '操作员';
                deriveFrom <'MR-4'>;
                attribute '任务启动响应时间' :> ISQ::duration;
                attribute '任务停止响应时间' :> ISQ::duration;
                require constraint { '任务启动响应时间' <= 3.0 * SI::s }
                require constraint { '任务停止响应时间' <= 3.0 * SI::s }
            }

            requirement <'SR-7'> '监视模式切换' {
                doc /* 响应模式切换指令并调整任务调度和观测处理流程 */
                text = """系统应响应操作员发出的有效监视模式切换指令，调整与监视模式相关的任务调度和观测处理流程，并反馈模式切换结果及当前任务状态。""";
                subject '系统' : '雷达系统';
                stakeholder '操作员' : '操作员';
