            doc /* 仅在模式、循环或玻璃加热请求及保护条件满足时使能。 */
            end sourcePort : HeaterCmdPort;
            end sinkPort : ~HeaterCmdPort;
            flow from sourcePort.command to sinkPort.command;
        }

    port def HeaterFeedbackPort {
            out item status : HeaterStatus;
        }

        interface def HeaterFeedbackLink {
