    port def ZoneAirCmdPort {
            out item command : FourZoneAirCommand;
        }

        interface def ZoneAirCmdLink {
            doc /* 四区风量、吹向及温湿度目标由 TMU 下发，前挡请求可优先分配风量。 */
            end sourcePort : ZoneAirCmdPort;
            end sinkPort : ~ZoneAirCmdPort;
