        }

    port def DriverCmdPort {
            out item request : DriverClimateRequest;
        }

        interface def DriverCmdLink {
            doc /* 驾驶员请求包括左前区舒适目标以及前后挡除雾除霜操作。 */
            end sourcePort : DriverCmdPort;
