        }

    port def RemoteRequestPort {
            out item request : RemoteRequest;
        }

        interface def RemoteRequestLink {
            doc /* 手机提交即时或预约请求，按 requestId 对应结果。 */
            end sourcePort : RemoteRequestPort;
            end sinkPort : ~RemoteRequestPort;
            flow from sourcePort.request to sinkPort.request;
        }

    port def RemoteDispatchPort {
            out item request : RemoteDispatch;
        }

        interface def RemoteDispatchLink {
            doc /* 网关向 TMU 提供准入判定，预约到期且条件通过才可执行相应模式。 */
            end sourcePort : RemoteDispatchPort;
            end sinkPort : ~RemoteDispatchPort;
