    port def RemoteFeedbackPort {
            out item status : RemoteStatus;
        }

        interface def RemoteFeedbackLink {
            doc /* 按原请求标识回传预约、拒绝、执行、完成或故障终止。 */
            end sourcePort : RemoteFeedbackPort;
            end sinkPort : ~RemoteFeedbackPort;
            flow from sourcePort.status to sinkPort.status;
        }

    // 冷媒循环，冷量耦合及冷却液回路。
    part def Compressor {
        doc /* 压缩机集成吸排气压力与温度传感器。失效或停机由独立反馈端口回传。 */
        port refrigerantLPVaporIn : ~RefrigerantLPVaporPort;
        port refrigerantHPVaporOut : RefrigerantHPVaporPort;
        port compressorCommandIn : ~RotaryCmdPort;
        port compressorStatusOut : RotaryFeedbackPort;
        port refrigerantSampleOut : RefrigerantFeedbackPort;
    }

    part def Condenser {
        doc /* 冷媒冷凝并向外部空气放热。 */
        port refrigerantHPVaporIn : ~RefrigerantHPVaporPort;
        port refrigerantHPLiquidOut : RefrigerantHPLiquidPort;
        port coolingAirIn : ~AirPort;
        port exhaustAirOut : AirPort;
    }

    part def LiquidHeader {
        doc /* 两个支路由各自的电子膨胀阀计量。 */
        port refrigerantHPLiquidIn : ~RefrigerantHPLiquidPort;
        port cabinHPLiquidOut : RefrigerantHPLiquidPort;
        port chillerHPLiquidOut : RefrigerantHPLiquidPort;
    }

    part def ExpansionValve {
        doc /* 压降发生于阀内。停机或失去有效驱动时关闭。 */
        port refrigerantHPLiquidIn : ~RefrigerantHPLiquidPort;
        port refrigerantLPMixtureOut : RefrigerantLPMixturePort;
        port expansionValveCommandIn : ~ValveCmdPort;
        port expansionValveStatusOut : ValveFeedbackPort;
    }

    part def CabinEvaporator {
        doc /* 冷媒蒸发时从空气吸热，达到露点时产生除湿。风侧在停用制冷时仍允许通风。冷凝水排放属于本部件边界。 */
        port refrigerantLPMixtureIn : ~RefrigerantLPMixturePort;
        port refrigerantLPVaporOut : RefrigerantLPVaporPort;
        port supplyAirIn : ~AirPort;
        port coldDryAirOut : AirPort;
    }

    part def Chiller {
        doc /* 隔壁式换热器。冷媒在低压侧蒸发并从低温冷却液吸热，给冷却液提供冷量。两侧分别守恒，各自有独立的入口和出口。 */
        port refrigerantLPMixtureIn : ~RefrigerantLPMixturePort;
        port refrigerantLPVaporOut : RefrigerantLPVaporPort;
        port ltCoolantWarmIn : ~LTCoolantPort;
        port ltCoolantCooledOut : LTCoolantPort;

        attribute coolingEnabled : Boolean;
        attribute coolingPower : PowerValue;

        doc /* 采用稳态、忽略壁体储热与对外散热的接口方程。冷量为正时，热量从冷却液传向冷媒。 */
        assert constraint steadyHeatExchange {
            ((not coolingEnabled) implies (coolingPower == 0[W])) and
            (coolingEnabled implies
                (refrigerantLPMixtureIn.refrigerant.massFlow == refrigerantLPVaporOut.refrigerant.massFlow and
                 ltCoolantWarmIn.coolant.massFlow == ltCoolantCooledOut.coolant.massFlow and
                 coolingPower == ltCoolantWarmIn.coolant.massFlow *
                     (ltCoolantWarmIn.coolant.specificEnthalpy - ltCoolantCooledOut.coolant.specificEnthalpy) and
                 coolingPower == refrigerantLPMixtureIn.refrigerant.massFlow *
                     (refrigerantLPVaporOut.refrigerant.specificEnthalpy - refrigerantLPMixtureIn.refrigerant.specificEnthalpy) and
                 ltCoolantWarmIn.coolant.specificEnthalpy >= ltCoolantCooledOut.coolant.specificEnthalpy and
                 refrigerantLPVaporOut.refrigerant.specificEnthalpy >= refrigerantLPMixtureIn.refrigerant.specificEnthalpy))
        }
    }

    part def SuctionHeader {
        doc /* 两支路在低压侧汇合。 */
        port cabinLPVaporIn : ~RefrigerantLPVaporPort;
        port chillerLPVaporIn : ~RefrigerantLPVaporPort;
        port refrigerantLPVaporOut : RefrigerantLPVaporPort;
    }

    part def HTPump {
        doc /* 高温泵集成出水温度、压力和流量采样。故障或停机经独立状态接口反馈。 */
        port htCoolantReturnIn : ~HTCoolantPort;
        port htCoolantSupplyOut : HTCoolantPort;
