    part def LTPump {
        doc /* 低温泵集成出水温度、压力和流量采样。故障或停机经独立状态接口反馈。 */
        port ltCoolantReturnIn : ~LTCoolantPort;
        port ltCoolantSupplyOut : LTCoolantPort;
        port pumpCommandIn : ~RotaryCmdPort;
        port pumpStatusOut : RotaryFeedbackPort;
        port coolantSampleOut : CoolantFeedbackPort;
    }

    part def LTRadiatorSelector {
        doc /* 低温三通阀的开度决定散热器分流；0 为完全旁通，1 为全量经散热器。 */
        port ltCoolantIn : ~LTCoolantPort;
        port ltCoolantToRadiatorOut : LTCoolantPort;
        port ltCoolantBypassOut : LTCoolantPort;
        port selectorCommandIn : ~ValveCmdPort;
        port selectorStatusOut : ValveFeedbackPort;
    }

    part def LTRadiator {
        doc /* 低温散热器将冷却液热量排向外部空气。 */
        port ltCoolantHotIn : ~LTCoolantPort;
        port ltCoolantCooledOut : LTCoolantPort;
        port coolingAirIn : ~AirPort;
        port exhaustAirOut : AirPort;
    }

    part def LTReturnHeader {
        doc /* 低温散热器与旁通支路在回水侧汇合。 */
