    part def DryAirPlenum {
        doc /* 冷干风分向四区混风通道及暖风芯体。 */
        port coldDryAirIn : ~AirPort;
        port coldDryAirToBlendOut : AirPort;
        port coldDryAirToHeaterOut : AirPort;
    }

    part def FourZoneAirDistributor {
        doc /* 每区独立混风、节流和调向。湿度通过共用蒸发器和新风配比调节。四区湿度目标参与控制，受共享除湿能力约束。前挡专用风路在潮湿工况下可送经再热的除湿风，在结霜工况下可送暖风。 */
        port coldDryAirIn : ~AirPort;
        port warmAirIn : ~AirPort;
        port leftFrontSupplyAirOut : AirPort;
        port rightFrontSupplyAirOut : AirPort;
        port leftRearSupplyAirOut : AirPort;
        port rightRearSupplyAirOut : AirPort;
