        port rearHeaterCommandIn : ~HeaterCmdPort;
        port rearHeaterStatusOut : HeaterFeedbackPort;
        port rearGlassHeatOut : ThermalPort;
    }

    // 人机接口、外部空气、座舱和传感器。
    part def Phone {
        port remoteRequestOut : RemoteRequestPort;
        port remoteStatusIn : ~RemoteFeedbackPort;
    }

    part def Driver {
        port driverClimateRequestOut : DriverCmdPort;
    }

    part def Passengers {
        port passengerClimateRequestOut : PassengerCmdPort;
    }

    part def TelematicsGateway {
        port remoteRequestIn : ~RemoteRequestPort;
        port remoteDispatchOut : RemoteDispatchPort;
        port remoteStatusIn : ~RemoteFeedbackPort;
        port remoteStatusOut : RemoteFeedbackPort;
    }

    part def AmbientEnvironment {
        doc /* 外部环境包含环境温湿度测点。 */
        port freshAirOut : AirPort;
        port cabinExhaustAirIn : ~AirPort;
        port condenserAmbientAirOut : AirPort;
        port condenserExhaustAirIn : ~AirPort;
        port htRadiatorAmbientAirOut : AirPort;
        port htRadiatorExhaustAirIn : ~AirPort;
        port ltRadiatorAmbientAirOut : AirPort;
        port ltRadiatorExhaustAirIn : ~AirPort;
        port ambientSampleOut : AmbientFeedbackPort;
    }

    part def CabinEnvironment {
        doc /* 包含四区温湿度传感器和前后挡表面测量。前挡风进入近玻璃区域后汇入座舱，送入的新风由被动排气路径平衡。 */
        port leftFrontSupplyAirIn : ~AirPort;
        port rightFrontSupplyAirIn : ~AirPort;
        port leftRearSupplyAirIn : ~AirPort;
        port rightRearSupplyAirIn : ~AirPort;
        port frontGlassAirIn : ~AirPort;
        port cabinReturnAirOut : AirPort;
        port cabinExhaustAirOut : AirPort;
        port rearGlassHeatIn : ~ThermalPort;
        port cabinSampleOut : CabinFeedbackPort;
        port glassSampleOut : GlassFeedbackPort;
    }

    part def ThermalManagementUnit {
        doc /* TMU 根据座舱设定、远程请求、传感器及执行器反馈进行模式选择和保护。frontDefog 为前挡除雾除霜模式，可优先分配送风；后挡加热可与其它模式并行。关键反馈超时按不可用处理。 */
        port compressorCommandOut : RotaryCmdPort;
        port compressorStatusIn : ~RotaryFeedbackPort;
        port cabinExpansionValveCommandOut : ValveCmdPort;
        port cabinExpansionValveStatusIn : ~ValveFeedbackPort;
        port chillerExpansionValveCommandOut : ValveCmdPort;
        port chillerExpansionValveStatusIn : ~ValveFeedbackPort;
        port htPumpCommandOut : RotaryCmdPort;
        port htPumpStatusIn : ~RotaryFeedbackPort;
        port ltPumpCommandOut : RotaryCmdPort;
        port ltPumpStatusIn : ~RotaryFeedbackPort;
        port htRadiatorSelectorCommandOut : ValveCmdPort;
        port htRadiatorSelectorStatusIn : ~ValveFeedbackPort;
        port ltRadiatorSelectorCommandOut : ValveCmdPort;
        port ltRadiatorSelectorStatusIn : ~ValveFeedbackPort;
        port coolantHeaterCommandOut : HeaterCmdPort;
        port coolantHeaterStatusIn : ~HeaterFeedbackPort;
        port condenserFanCommandOut : FanCmdPort;
        port condenserFanStatusIn : ~FanFeedbackPort;
        port htRadiatorFanCommandOut : FanCmdPort;
        port htRadiatorFanStatusIn : ~FanFeedbackPort;
        port ltRadiatorFanCommandOut : FanCmdPort;
        port ltRadiatorFanStatusIn : ~FanFeedbackPort;
        port airInletMixerCommandOut : ValveCmdPort;
        port airInletMixerStatusIn : ~ValveFeedbackPort;
        port cabinBlowerCommandOut : RotaryCmdPort;
        port cabinBlowerStatusIn : ~RotaryFeedbackPort;
        port zoneDistributorCommandOut : ZoneAirCmdPort;
        port zoneDistributorStatusIn : ~ZoneAirFeedbackPort;
        port rearHeaterCommandOut : HeaterCmdPort;
        port rearHeaterStatusIn : ~HeaterFeedbackPort;
        port driverClimateRequestIn : ~DriverCmdPort;
        port passengerClimateRequestIn : ~PassengerCmdPort;
        port remoteDispatchIn : ~RemoteDispatchPort;
        port remoteStatusOut : RemoteFeedbackPort;
        port ambientSampleIn : ~AmbientFeedbackPort;
        port cabinSampleIn : ~CabinFeedbackPort;
        port glassSampleIn : ~GlassFeedbackPort;
        port refrigerantSampleIn : ~RefrigerantFeedbackPort;
        port htCoolantSampleIn : ~CoolantFeedbackPort;
        port ltCoolantSampleIn : ~CoolantFeedbackPort;

        attribute mode : ThermalMode;
        attribute compressorFeedbackFresh : Boolean;
        attribute htPumpFeedbackFresh : Boolean;
        attribute ltPumpFeedbackFresh : Boolean;
        attribute refrigerantProtectionPermits : Boolean;
        attribute htCirculationConfirmed : Boolean;
        attribute ltCirculationConfirmed : Boolean;
        attribute chillerCoolingRequested : Boolean;
        attribute htHeatRejectionRequested : Boolean;
        attribute ltRadiatorBeneficial : Boolean;
        attribute frontReheatRequested : Boolean;
        attribute rearHeatPermitted : Boolean;

        doc /* 以上许可由 TMU 根据反馈时效、压力温度与过热度边界、实际流量、温差和玻璃状态求取。
             * 数值边界、滞环及报文超时按项目标定。循环确认依赖有效、达到下限的实测流量。
             * 低温散热器只在环境温度和冷却液温度允许向外散热时选通。
             */

        attribute compressorHealthy : Boolean = compressorFeedbackFresh and
            compressorStatusIn.status.available and not compressorStatusIn.status.faultActive;
        attribute htPumpHealthy : Boolean = htPumpFeedbackFresh and
            htPumpStatusIn.status.available and not htPumpStatusIn.status.faultActive;
        attribute ltPumpHealthy : Boolean = ltPumpFeedbackFresh and
            ltPumpStatusIn.status.available and not ltPumpStatusIn.status.faultActive;
        attribute cabinCoolingMode : Boolean = mode == ThermalMode::zoneCooling or
            mode == ThermalMode::remoteCooling or mode == ThermalMode::frontDefog;
        attribute cabinHeatingMode : Boolean = mode == ThermalMode::zoneHeating or
            mode == ThermalMode::remotePreheating;
        attribute chillerPermitted : Boolean = chillerCoolingRequested and
            (mode == ThermalMode::zoneCooling or mode == ThermalMode::remoteCooling) and
            ltPumpHealthy and ltCirculationConfirmed and ltCoolantSampleIn.sample.valid;

        assert constraint refrigerantProtection {
            (compressorCommandOut.command.enable implies
                (compressorHealthy and refrigerantSampleIn.sample.valid and refrigerantProtectionPermits)) and
            ((not compressorHealthy or not refrigerantProtectionPermits or not refrigerantSampleIn.sample.valid) implies
                (cabinExpansionValveCommandOut.command.openingFraction == 0.0 and
                 chillerExpansionValveCommandOut.command.openingFraction == 0.0))
        }

        assert constraint cabinExpansionAllowed {
            (cabinExpansionValveCommandOut.command.openingFraction > 0.0) implies
                (cabinCoolingMode and compressorCommandOut.command.enable and
                 cabinBlowerCommandOut.command.enable)
        }

        assert constraint chillerExpansionAllowed {
            (chillerExpansionValveCommandOut.command.openingFraction > 0.0) implies
                (chillerPermitted and compressorCommandOut.command.enable and ltPumpCommandOut.command.enable)
        }

        assert constraint compressorRequiresAnEvaporationPath {
            compressorCommandOut.command.enable implies
                (cabinExpansionValveCommandOut.command.openingFraction > 0.0 or
                 chillerExpansionValveCommandOut.command.openingFraction > 0.0)
        }

        assert constraint stopFailedPumps {
            ((not htPumpHealthy) implies (not htPumpCommandOut.command.enable)) and
            ((not ltPumpHealthy) implies (not ltPumpCommandOut.command.enable))
        }

        assert constraint coolantHeatRequiresCirculation {
            coolantHeaterCommandOut.command.enable implies
                (htPumpHealthy and htPumpCommandOut.command.enable and htCirculationConfirmed and
                 htCoolantSampleIn.sample.valid and coolantHeaterStatusIn.status.available and
                 not coolantHeaterStatusIn.status.overtemperature and not coolantHeaterStatusIn.status.faultActive and
                 (cabinHeatingMode or (mode == ThermalMode::frontDefog and frontReheatRequested)))
        }

        assert constraint radiatorSelection {
            ((not htHeatRejectionRequested or coolantHeaterCommandOut.command.enable) implies
                (htRadiatorSelectorCommandOut.command.openingFraction == 0.0)) and
            ((not ltRadiatorBeneficial) implies (ltRadiatorSelectorCommandOut.command.openingFraction == 0.0))
        }

        assert constraint frontDefogRouting {
            (mode == ThermalMode::frontDefog) implies
                (zoneDistributorCommandOut.command.frontDefog and cabinBlowerCommandOut.command.enable and
                 airInletMixerCommandOut.command.openingFraction > 0.0)
        }

        assert constraint frontFrostNeedsReheat {
            (mode == ThermalMode::frontDefog and glassSampleIn.sample.valid and
             glassSampleIn.sample.frontSurfaceState == GlassSurfaceState::frosted) implies frontReheatRequested
        }

        assert constraint rearWindowHeatProtection {
            rearHeaterCommandOut.command.enable implies
                (driverClimateRequestIn.request.rearDefrostRequested and rearHeatPermitted and
                 glassSampleIn.sample.valid and rearHeaterStatusIn.status.available and
                 not rearHeaterStatusIn.status.overtemperature and not rearHeaterStatusIn.status.faultActive)
        }

        assert constraint runningRemoteRequestIsCorrelated {
            ((mode == ThermalMode::remoteCooling or mode == ThermalMode::remotePreheating) and
                remoteStatusOut.status.requestState == RemoteRequestState::running) implies
                (remoteStatusOut.status.requestId == remoteDispatchIn.request.requestId and
                 remoteStatusOut.status.currentMode == mode)
        }

        assert constraint remoteAdmission {
            ((mode == ThermalMode::remoteCooling) implies
                (remoteDispatchIn.request.mayStart and compressorHealthy and refrigerantSampleIn.sample.valid and
                 remoteDispatchIn.request.operation == RemoteOperation::coolCabin)) and
            ((mode == ThermalMode::remotePreheating) implies
                (remoteDispatchIn.request.mayStart and htPumpHealthy and htCoolantSampleIn.sample.valid and
                 remoteDispatchIn.request.operation == RemoteOperation::preheatCabin))
        }
    }

    part def ThermalManagementSystem {
        doc /* TMS 内部模块和接口拓扑。外部端口按同向委托接到内部端口，再由整车场景连接利益相关方。 */
        port remoteRequestIn : ~RemoteRequestPort;
        port remoteStatusOut : RemoteFeedbackPort;
        port driverClimateRequestIn : ~DriverCmdPort;
        port passengerClimateRequestIn : ~PassengerCmdPort;
        port ambientSampleIn : ~AmbientFeedbackPort;
        port cabinSampleIn : ~CabinFeedbackPort;
        port glassSampleIn : ~GlassFeedbackPort;
        port ambientFreshAirIn : ~AirPort;
        port cabinReturnAirIn : ~AirPort;
        port leftFrontSupplyAirOut : AirPort;
        port rightFrontSupplyAirOut : AirPort;
        port leftRearSupplyAirOut : AirPort;
        port rightRearSupplyAirOut : AirPort;
        port frontGlassAirOut : AirPort;
        port rearGlassHeatOut : ThermalPort;
        port condenserAmbientAirIn : ~AirPort;
        port condenserExhaustAirOut : AirPort;
        port htRadiatorAmbientAirIn : ~AirPort;
        port htRadiatorExhaustAirOut : AirPort;
        port ltRadiatorAmbientAirIn : ~AirPort;
        port ltRadiatorExhaustAirOut : AirPort;

        part tmu : ThermalManagementUnit;
        part gateway : TelematicsGateway;
        part compressor : Compressor;
        part cabinExpansionValve : ExpansionValve;
        part chillerExpansionValve : ExpansionValve;
        part htPump : HTPump;
        part ltPump : LTPump;
        part htRadiatorSelector : HTRadiatorSelector;
        part ltRadiatorSelector : LTRadiatorSelector;
        part coolantHeater : ElectricCoolantHeater;
        part condenserFan : HeatRejectionFan;
        part htRadiatorFan : HeatRejectionFan;
        part ltRadiatorFan : HeatRejectionFan;
        part airInletMixer : AirInletMixer;
        part cabinBlower : CabinBlower;
        part zoneDistributor : FourZoneAirDistributor;
        part rearHeater : RearDefrostHeater;
        part condenser : Condenser;
        part liquidHeader : LiquidHeader;
        part cabinEvaporator : CabinEvaporator;
        part chiller : Chiller;
        part suctionHeader : SuctionHeader;
        part htRadiator : HTRadiator;
        part htReturnHeader : HTReturnHeader;
        part cabinHeaterCore : CabinHeaterCore;
        part ltRadiator : LTRadiator;
        part ltReturnHeader : LTReturnHeader;
        part electronicsColdPlate : ElectronicsColdPlate;
        part dryAirPlenum : DryAirPlenum;

        // 冷媒循环。冷凝侧为高压，节流后为低压，回气为低压气相。
        interface refrigerantDischarge : RefrigerantHPVaporLink connect
                sourcePort ::> compressor.refrigerantHPVaporOut to
                sinkPort ::> condenser.refrigerantHPVaporIn;
        interface refrigerantLiquidSupply : RefrigerantHPLiquidLink connect
                sourcePort ::> condenser.refrigerantHPLiquidOut to
                sinkPort ::> liquidHeader.refrigerantHPLiquidIn;
        interface cabinLiquidLine : RefrigerantHPLiquidLink connect
                sourcePort ::> liquidHeader.cabinHPLiquidOut to
                sinkPort ::> cabinExpansionValve.refrigerantHPLiquidIn;
        interface cabinTwoPhaseLine : RefrigerantLPMixtureLink connect
                sourcePort ::> cabinExpansionValve.refrigerantLPMixtureOut to
                sinkPort ::> cabinEvaporator.refrigerantLPMixtureIn;
        interface cabinSuctionLine : RefrigerantLPVaporLink connect
                sourcePort ::> cabinEvaporator.refrigerantLPVaporOut to
                sinkPort ::> suctionHeader.cabinLPVaporIn;
        interface chillerLiquidLine : RefrigerantHPLiquidLink connect
                sourcePort ::> liquidHeader.chillerHPLiquidOut to
                sinkPort ::> chillerExpansionValve.refrigerantHPLiquidIn;
        interface chillerTwoPhaseLine : RefrigerantLPMixtureLink connect
                sourcePort ::> chillerExpansionValve.refrigerantLPMixtureOut to
                sinkPort ::> chiller.refrigerantLPMixtureIn;
        interface chillerSuctionLine : RefrigerantLPVaporLink connect
                sourcePort ::> chiller.refrigerantLPVaporOut to
                sinkPort ::> suctionHeader.chillerLPVaporIn;
        interface refrigerantReturn : RefrigerantLPVaporLink connect
                sourcePort ::> suctionHeader.refrigerantLPVaporOut to
                sinkPort ::> compressor.refrigerantLPVaporIn;

        // 高温冷却液循环。采暖时散热器旁通。
        interface htPumpSupply : HTCoolantLink connect
                sourcePort ::> htPump.htCoolantSupplyOut to
                sinkPort ::> coolantHeater.htCoolantIn;
        interface htHeaterToCore : HTCoolantLink connect
                sourcePort ::> coolantHeater.htCoolantHeatedOut to
                sinkPort ::> cabinHeaterCore.htCoolantHotIn;
        interface htCoreToSelector : HTCoolantLink connect
                sourcePort ::> cabinHeaterCore.htCoolantReturnOut to
                sinkPort ::> htRadiatorSelector.htCoolantIn;
        interface htRadiatorFeed : HTCoolantLink connect
                sourcePort ::> htRadiatorSelector.htCoolantToRadiatorOut to
                sinkPort ::> htRadiator.htCoolantHotIn;
        interface htBypass : HTCoolantLink connect
                sourcePort ::> htRadiatorSelector.htCoolantBypassOut to
                sinkPort ::> htReturnHeader.htCoolantBypassIn;
        interface htRadiatorReturn : HTCoolantLink connect
                sourcePort ::> htRadiator.htCoolantCooledOut to
                sinkPort ::> htReturnHeader.htCoolantRadiatorIn;
        interface htPumpReturn : HTCoolantLink connect
                sourcePort ::> htReturnHeader.htCoolantReturnOut to
                sinkPort ::> htPump.htCoolantReturnIn;

        // 低温冷却液循环。Chiller 串接于回水段，由其冷媒侧阀决定是否主动制冷。
        interface ltPumpSupply : LTCoolantLink connect
                sourcePort ::> ltPump.ltCoolantSupplyOut to
                sinkPort ::> electronicsColdPlate.ltCoolantCooledIn;
        interface ltLoadToSelector : LTCoolantLink connect
                sourcePort ::> electronicsColdPlate.ltCoolantWarmOut to
                sinkPort ::> ltRadiatorSelector.ltCoolantIn;
        interface ltRadiatorFeed : LTCoolantLink connect
                sourcePort ::> ltRadiatorSelector.ltCoolantToRadiatorOut to
                sinkPort ::> ltRadiator.ltCoolantHotIn;
        interface ltBypass : LTCoolantLink connect
                sourcePort ::> ltRadiatorSelector.ltCoolantBypassOut to
                sinkPort ::> ltReturnHeader.ltCoolantBypassIn;
        interface ltRadiatorReturn : LTCoolantLink connect
                sourcePort ::> ltRadiator.ltCoolantCooledOut to
                sinkPort ::> ltReturnHeader.ltCoolantRadiatorIn;
        interface ltChillerFeed : LTCoolantLink connect
                sourcePort ::> ltReturnHeader.ltCoolantReturnOut to
                sinkPort ::> chiller.ltCoolantWarmIn;
        interface ltPumpReturn : LTCoolantLink connect
                sourcePort ::> chiller.ltCoolantCooledOut to
                sinkPort ::> ltPump.ltCoolantReturnIn;

        // 舱内送风与室外散热风路。
        interface mixedAir : AirLink connect
                sourcePort ::> airInletMixer.mixedAirOut to
                sinkPort ::> cabinBlower.mixedAirIn;
        interface airToEvaporator : AirLink connect
                sourcePort ::> cabinBlower.pressurizedAirOut to
                sinkPort ::> cabinEvaporator.supplyAirIn;
        interface airToDryPlenum : AirLink connect
                sourcePort ::> cabinEvaporator.coldDryAirOut to
                sinkPort ::> dryAirPlenum.coldDryAirIn;
        interface dryAirToBlend : AirLink connect
                sourcePort ::> dryAirPlenum.coldDryAirToBlendOut to
                sinkPort ::> zoneDistributor.coldDryAirIn;
        interface dryAirToHeater : AirLink connect
                sourcePort ::> dryAirPlenum.coldDryAirToHeaterOut to
                sinkPort ::> cabinHeaterCore.coldDryAirIn;
        interface warmAirToBlend : AirLink connect
                sourcePort ::> cabinHeaterCore.warmAirOut to
                sinkPort ::> zoneDistributor.warmAirIn;
        interface condenserForcedAir : AirLink connect
                sourcePort ::> condenserFan.forcedAirOut to
                sinkPort ::> condenser.coolingAirIn;
        interface htRadiatorForcedAir : AirLink connect
                sourcePort ::> htRadiatorFan.forcedAirOut to
                sinkPort ::> htRadiator.coolingAirIn;
        interface ltRadiatorForcedAir : AirLink connect
                sourcePort ::> ltRadiatorFan.forcedAirOut to
                sinkPort ::> ltRadiator.coolingAirIn;

        // 控制信号。TMU 每个输出只接对应执行器的指令输入。
        interface compressorControl : RotaryCmdLink connect
                sourcePort ::> tmu.compressorCommandOut to
                sinkPort ::> compressor.compressorCommandIn;
        interface cabinExpansionValveControl : ValveCmdLink connect
                sourcePort ::> tmu.cabinExpansionValveCommandOut to
                sinkPort ::> cabinExpansionValve.expansionValveCommandIn;
        interface chillerExpansionValveControl : ValveCmdLink connect
                sourcePort ::> tmu.chillerExpansionValveCommandOut to
                sinkPort ::> chillerExpansionValve.expansionValveCommandIn;
        interface htPumpControl : RotaryCmdLink connect
                sourcePort ::> tmu.htPumpCommandOut to
                sinkPort ::> htPump.pumpCommandIn;
        interface ltPumpControl : RotaryCmdLink connect
                sourcePort ::> tmu.ltPumpCommandOut to
                sinkPort ::> ltPump.pumpCommandIn;
        interface htRadiatorSelectorControl : ValveCmdLink connect
                sourcePort ::> tmu.htRadiatorSelectorCommandOut to
                sinkPort ::> htRadiatorSelector.selectorCommandIn;
        interface ltRadiatorSelectorControl : ValveCmdLink connect
                sourcePort ::> tmu.ltRadiatorSelectorCommandOut to
                sinkPort ::> ltRadiatorSelector.selectorCommandIn;
        interface coolantHeaterControl : HeaterCmdLink connect
                sourcePort ::> tmu.coolantHeaterCommandOut to
                sinkPort ::> coolantHeater.coolantHeaterCommandIn;
        interface condenserFanControl : FanCmdLink connect
                sourcePort ::> tmu.condenserFanCommandOut to
                sinkPort ::> condenserFan.fanCommandIn;
        interface htRadiatorFanControl : FanCmdLink connect
                sourcePort ::> tmu.htRadiatorFanCommandOut to
                sinkPort ::> htRadiatorFan.fanCommandIn;
        interface ltRadiatorFanControl : FanCmdLink connect
                sourcePort ::> tmu.ltRadiatorFanCommandOut to
                sinkPort ::> ltRadiatorFan.fanCommandIn;
        interface airInletMixerControl : ValveCmdLink connect
                sourcePort ::> tmu.airInletMixerCommandOut to
                sinkPort ::> airInletMixer.freshAirDoorCommandIn;
        interface cabinBlowerControl : RotaryCmdLink connect
                sourcePort ::> tmu.cabinBlowerCommandOut to
                sinkPort ::> cabinBlower.blowerCommandIn;
        interface zoneDistributorControl : ZoneAirCmdLink connect
                sourcePort ::> tmu.zoneDistributorCommandOut to
                sinkPort ::> zoneDistributor.zoneAirCommandIn;
        interface rearHeaterControl : HeaterCmdLink connect
                sourcePort ::> tmu.rearHeaterCommandOut to
                sinkPort ::> rearHeater.rearHeaterCommandIn;
        interface remoteDispatchToTmu : RemoteDispatchLink connect
                sourcePort ::> gateway.remoteDispatchOut to
                sinkPort ::> tmu.remoteDispatchIn;

        // 状态反馈。每路执行器状态及传感器采样分别接入 TMU。
        interface compressorFeedback : RotaryFeedbackLink connect
                sourcePort ::> compressor.compressorStatusOut to
                sinkPort ::> tmu.compressorStatusIn;
        interface cabinExpansionValveFeedback : ValveFeedbackLink connect
                sourcePort ::> cabinExpansionValve.expansionValveStatusOut to
                sinkPort ::> tmu.cabinExpansionValveStatusIn;
        interface chillerExpansionValveFeedback : ValveFeedbackLink connect
                sourcePort ::> chillerExpansionValve.expansionValveStatusOut to
                sinkPort ::> tmu.chillerExpansionValveStatusIn;
        interface htPumpFeedback : RotaryFeedbackLink connect
                sourcePort ::> htPump.pumpStatusOut to
                sinkPort ::> tmu.htPumpStatusIn;
        interface ltPumpFeedback : RotaryFeedbackLink connect
                sourcePort ::> ltPump.pumpStatusOut to
                sinkPort ::> tmu.ltPumpStatusIn;
        interface htRadiatorSelectorFeedback : ValveFeedbackLink connect
                sourcePort ::> htRadiatorSelector.selectorStatusOut to
                sinkPort ::> tmu.htRadiatorSelectorStatusIn;
        interface ltRadiatorSelectorFeedback : ValveFeedbackLink connect
                sourcePort ::> ltRadiatorSelector.selectorStatusOut to
                sinkPort ::> tmu.ltRadiatorSelectorStatusIn;
        interface coolantHeaterFeedback : HeaterFeedbackLink connect
                sourcePort ::> coolantHeater.coolantHeaterStatusOut to
                sinkPort ::> tmu.coolantHeaterStatusIn;
        interface condenserFanFeedback : FanFeedbackLink connect
                sourcePort ::> condenserFan.fanStatusOut to
                sinkPort ::> tmu.condenserFanStatusIn;
        interface htRadiatorFanFeedback : FanFeedbackLink connect
                sourcePort ::> htRadiatorFan.fanStatusOut to
                sinkPort ::> tmu.htRadiatorFanStatusIn;
        interface ltRadiatorFanFeedback : FanFeedbackLink connect
                sourcePort ::> ltRadiatorFan.fanStatusOut to
                sinkPort ::> tmu.ltRadiatorFanStatusIn;
        interface airInletMixerFeedback : ValveFeedbackLink connect
                sourcePort ::> airInletMixer.freshAirDoorStatusOut to
                sinkPort ::> tmu.airInletMixerStatusIn;
        interface cabinBlowerFeedback : RotaryFeedbackLink connect
                sourcePort ::> cabinBlower.blowerStatusOut to
                sinkPort ::> tmu.cabinBlowerStatusIn;
        interface zoneDistributorFeedback : ZoneAirFeedbackLink connect
                sourcePort ::> zoneDistributor.zoneAirStatusOut to
                sinkPort ::> tmu.zoneDistributorStatusIn;
        interface rearHeaterFeedback : HeaterFeedbackLink connect
                sourcePort ::> rearHeater.rearHeaterStatusOut to
                sinkPort ::> tmu.rearHeaterStatusIn;
        interface refrigerantMeasurements : RefrigerantFeedbackLink connect
                sourcePort ::> compressor.refrigerantSampleOut to
                sinkPort ::> tmu.refrigerantSampleIn;
        interface htCoolantMeasurements : CoolantFeedbackLink connect
                sourcePort ::> htPump.coolantSampleOut to
                sinkPort ::> tmu.htCoolantSampleIn;
        interface ltCoolantMeasurements : CoolantFeedbackLink connect
                sourcePort ::> ltPump.coolantSampleOut to
                sinkPort ::> tmu.ltCoolantSampleIn;
        interface remoteStatusToGateway : RemoteFeedbackLink connect
                sourcePort ::> tmu.remoteStatusOut to
                sinkPort ::> gateway.remoteStatusIn;

        // 边界委托。同一端口类型在边界与内部端口间传递同一载荷。
        connection delegateRemoteRequestIn connect remoteRequestIn to gateway.remoteRequestIn;
        bind remoteRequestIn.request = gateway.remoteRequestIn.request;
        connection delegateRemoteStatusOut connect gateway.remoteStatusOut to remoteStatusOut;
        bind gateway.remoteStatusOut.status = remoteStatusOut.status;
        connection delegateDriverClimateRequestIn connect driverClimateRequestIn to tmu.driverClimateRequestIn;
        bind driverClimateRequestIn.request = tmu.driverClimateRequestIn.request;
        connection delegatePassengerClimateRequestIn connect passengerClimateRequestIn to tmu.passengerClimateRequestIn;
        bind passengerClimateRequestIn.request = tmu.passengerClimateRequestIn.request;
        connection delegateAmbientSampleIn connect ambientSampleIn to tmu.ambientSampleIn;
        bind ambientSampleIn.sample = tmu.ambientSampleIn.sample;
        connection delegateCabinSampleIn connect cabinSampleIn to tmu.cabinSampleIn;
        bind cabinSampleIn.sample = tmu.cabinSampleIn.sample;
        connection delegateGlassSampleIn connect glassSampleIn to tmu.glassSampleIn;
        bind glassSampleIn.sample = tmu.glassSampleIn.sample;
        connection delegateAmbientFreshAirIn connect ambientFreshAirIn to airInletMixer.freshAirIn;
        bind ambientFreshAirIn.air = airInletMixer.freshAirIn.air;
        connection delegateCabinReturnAirIn connect cabinReturnAirIn to airInletMixer.returnAirIn;
        bind cabinReturnAirIn.air = airInletMixer.returnAirIn.air;
        connection delegateLeftFrontSupplyAirOut connect zoneDistributor.leftFrontSupplyAirOut to leftFrontSupplyAirOut;
        bind zoneDistributor.leftFrontSupplyAirOut.air = leftFrontSupplyAirOut.air;
        connection delegateRightFrontSupplyAirOut connect zoneDistributor.rightFrontSupplyAirOut to rightFrontSupplyAirOut;
        bind zoneDistributor.rightFrontSupplyAirOut.air = rightFrontSupplyAirOut.air;
        connection delegateLeftRearSupplyAirOut connect zoneDistributor.leftRearSupplyAirOut to leftRearSupplyAirOut;
        bind zoneDistributor.leftRearSupplyAirOut.air = leftRearSupplyAirOut.air;
        connection delegateRightRearSupplyAirOut connect zoneDistributor.rightRearSupplyAirOut to rightRearSupplyAirOut;
        bind zoneDistributor.rightRearSupplyAirOut.air = rightRearSupplyAirOut.air;
        connection delegateFrontGlassAirOut connect zoneDistributor.frontGlassAirOut to frontGlassAirOut;
        bind zoneDistributor.frontGlassAirOut.air = frontGlassAirOut.air;
        connection delegateRearGlassHeatOut connect rearHeater.rearGlassHeatOut to rearGlassHeatOut;
        bind rearHeater.rearGlassHeatOut.heat = rearGlassHeatOut.heat;
        connection delegateCondenserAmbientAirIn connect condenserAmbientAirIn to condenserFan.ambientAirIn;
        bind condenserAmbientAirIn.air = condenserFan.ambientAirIn.air;
        connection delegateCondenserExhaustAirOut connect condenser.exhaustAirOut to condenserExhaustAirOut;
        bind condenser.exhaustAirOut.air = condenserExhaustAirOut.air;
        connection delegateHtRadiatorAmbientAirIn connect htRadiatorAmbientAirIn to htRadiatorFan.ambientAirIn;
        bind htRadiatorAmbientAirIn.air = htRadiatorFan.ambientAirIn.air;
        connection delegateHtRadiatorExhaustAirOut connect htRadiator.exhaustAirOut to htRadiatorExhaustAirOut;
        bind htRadiator.exhaustAirOut.air = htRadiatorExhaustAirOut.air;
        connection delegateLtRadiatorAmbientAirIn connect ltRadiatorAmbientAirIn to ltRadiatorFan.ambientAirIn;
        bind ltRadiatorAmbientAirIn.air = ltRadiatorFan.ambientAirIn.air;
        connection delegateLtRadiatorExhaustAirOut connect ltRadiator.exhaustAirOut to ltRadiatorExhaustAirOut;
        bind ltRadiator.exhaustAirOut.air = ltRadiatorExhaustAirOut.air;

        assert constraint chillerEnableFollowsBranch {
            chiller.coolingEnabled == (tmu.chillerExpansionValveCommandOut.command.openingFraction > 0.0 and
                tmu.chillerExpansionValveStatusIn.status.available and
                not tmu.chillerExpansionValveStatusIn.status.faultActive and
                tmu.chillerExpansionValveStatusIn.status.actualOpeningFraction > 0.0 and
                tmu.compressorStatusIn.status.running and tmu.ltCirculationConfirmed)
        }
    }

    part vehicleThermalContext {
        doc /* 整车环境中的五类利益相关方及其 TMS 边界连接。 */
        part tms : ThermalManagementSystem;
        part phone : Phone;
        part driver : Driver;
        part passengers : Passengers;
        part ambient : AmbientEnvironment;
        part cabin : CabinEnvironment;

        interface boundaryRemoteRequestIn : RemoteRequestLink connect
                sourcePort ::> phone.remoteRequestOut to
                sinkPort ::> tms.remoteRequestIn;
        interface boundaryRemoteStatusOut : RemoteFeedbackLink connect
                sourcePort ::> tms.remoteStatusOut to
                sinkPort ::> phone.remoteStatusIn;
        interface boundaryDriverClimateRequestIn : DriverCmdLink connect
                sourcePort ::> driver.driverClimateRequestOut to
                sinkPort ::> tms.driverClimateRequestIn;
        interface boundaryPassengerClimateRequestIn : PassengerCmdLink connect
                sourcePort ::> passengers.passengerClimateRequestOut to
                sinkPort ::> tms.passengerClimateRequestIn;
        interface boundaryAmbientSampleIn : AmbientFeedbackLink connect
                sourcePort ::> ambient.ambientSampleOut to
                sinkPort ::> tms.ambientSampleIn;
        interface boundaryCabinSampleIn : CabinFeedbackLink connect
                sourcePort ::> cabin.cabinSampleOut to
                sinkPort ::> tms.cabinSampleIn;
        interface boundaryGlassSampleIn : GlassFeedbackLink connect
                sourcePort ::> cabin.glassSampleOut to
                sinkPort ::> tms.glassSampleIn;
        interface boundaryAmbientFreshAirIn : AirLink connect
                sourcePort ::> ambient.freshAirOut to
                sinkPort ::> tms.ambientFreshAirIn;
        interface boundaryCabinReturnAirIn : AirLink connect
                sourcePort ::> cabin.cabinReturnAirOut to
                sinkPort ::> tms.cabinReturnAirIn;
        interface boundaryLeftFrontSupplyAirOut : AirLink connect
                sourcePort ::> tms.leftFrontSupplyAirOut to
                sinkPort ::> cabin.leftFrontSupplyAirIn;
        interface boundaryRightFrontSupplyAirOut : AirLink connect
                sourcePort ::> tms.rightFrontSupplyAirOut to
                sinkPort ::> cabin.rightFrontSupplyAirIn;
        interface boundaryLeftRearSupplyAirOut : AirLink connect
                sourcePort ::> tms.leftRearSupplyAirOut to
                sinkPort ::> cabin.leftRearSupplyAirIn;
        interface boundaryRightRearSupplyAirOut : AirLink connect
                sourcePort ::> tms.rightRearSupplyAirOut to
                sinkPort ::> cabin.rightRearSupplyAirIn;
        interface boundaryFrontGlassAirOut : AirLink connect
                sourcePort ::> tms.frontGlassAirOut to
                sinkPort ::> cabin.frontGlassAirIn;
        interface boundaryRearGlassHeatOut : ThermalLink connect
                sourcePort ::> tms.rearGlassHeatOut to
                sinkPort ::> cabin.rearGlassHeatIn;
        interface boundaryCondenserAmbientAirIn : AirLink connect
                sourcePort ::> ambient.condenserAmbientAirOut to
                sinkPort ::> tms.condenserAmbientAirIn;
        interface boundaryCondenserExhaustAirOut : AirLink connect
                sourcePort ::> tms.condenserExhaustAirOut to
                sinkPort ::> ambient.condenserExhaustAirIn;
        interface boundaryHtRadiatorAmbientAirIn : AirLink connect
                sourcePort ::> ambient.htRadiatorAmbientAirOut to
                sinkPort ::> tms.htRadiatorAmbientAirIn;
        interface boundaryHtRadiatorExhaustAirOut : AirLink connect
                sourcePort ::> tms.htRadiatorExhaustAirOut to
                sinkPort ::> ambient.htRadiatorExhaustAirIn;
        interface boundaryLtRadiatorAmbientAirIn : AirLink connect
                sourcePort ::> ambient.ltRadiatorAmbientAirOut to
                sinkPort ::> tms.ltRadiatorAmbientAirIn;
        interface boundaryLtRadiatorExhaustAirOut : AirLink connect
                sourcePort ::> tms.ltRadiatorExhaustAirOut to
                sinkPort ::> ambient.ltRadiatorExhaustAirIn;
        interface cabinPassiveExhaust : AirLink connect
                sourcePort ::> cabin.cabinExhaustAirOut to
                sinkPort ::> ambient.cabinExhaustAirIn;
    }

    // 整车需求追溯，满足关系指向负责实现的 TMS。
    use case '夏季酷热早高峰四分区舒适温控' {
            doc /* 驾驶员与乘客设置四区温湿度、风量和吹向。TMU 启用座舱蒸发支路，使用四区实测状态闭环调节。 */
            subject systemUnderStudy : ThermalManagementSystem;
        }
        dependency scenario1Baseline from '夏季酷热早高峰四分区舒适温控' to '热管理相关需求集'::'提供舒适温度';
    use case '夏季暴晒后远程急速降温' {
            doc /* 手机请求即时降温。网关校验，TMU 启用座舱蒸发支路并经网关反馈请求状态。 */
            subject systemUnderStudy : ThermalManagementSystem;
        }
        dependency scenario2Baseline from '夏季暴晒后远程急速降温' to '热管理相关需求集'::'提供空调系统远程控制模式';
    use case '夏季湿热前挡除雾' {
            doc /* 优先向前挡送除湿风，按需再热，结合玻璃状态与邻域露点判断。后挡起雾或结霜时可独立请求电加热。 */
            subject systemUnderStudy : ThermalManagementSystem;
        }
        dependency scenario3Baseline from '夏季湿热前挡除雾' to '热管理相关需求集'::'除霜除雾';
    use case '冬季极寒远程预热' {
            doc /* 手机请求即时或预约预热。准入后，高温泵向 PTC 和暖风芯体供液，散热器旁通，暖风送入座舱。 */
            subject systemUnderStudy : ThermalManagementSystem;
        }
        dependency scenario4Baseline from '冬季极寒远程预热' to '热管理相关需求集'::'提供空调系统远程控制模式';

    satisfy '热管理相关需求集'::'提供舒适温度' by vehicleThermalContext.tms;
    satisfy '热管理相关需求集'::'提供空调系统远程控制模式' by vehicleThermalContext.tms;
    satisfy '热管理相关需求集'::'除霜除雾' by vehicleThermalContext.tms;

    view '热管理系统内部模块视图' : InterconnectionView {
        expose ThermalManagementSystem::*;
    }
}

