        action '控制热管理' : '功能步骤' { attribute '能量状态' : ScalarValues::Real; attribute '热管理状态' : ScalarValues::Boolean; }
        action '执行再生制动' : '功能步骤' { attribute '制动信号' : ScalarValues::Boolean; attribute '回收能量' : ScalarValues::Real; }
        action '检测特殊工况' : '功能步骤' { attribute '车辆状态' : ScalarValues::String; out attribute '特殊工况标志' : ScalarValues::Boolean; }
        action '激活雪地模式' : '功能步骤' { attribute '模式指令' : ScalarValues::String; }
        action '激活运动模式' : '功能步骤' { attribute '模式指令' : ScalarValues::String; }
        action '激活经济模式' : '功能步骤' { attribute '模式指令' : ScalarValues::String; }
        action '调整动力策略' : '功能步骤' { attribute '模式指令' : ScalarValues::String; attribute '调整后功率' : ScalarValues::Real; }
        action '检测关机请求' : '功能步骤' { attribute '关机信号' : ScalarValues::Boolean; }
        action '保存车辆状态' : '功能步骤' { attribute '车辆状态数据' : ScalarValues::String; }
        action '高压下电' : '功能步骤' { attribute '高压状态' : ScalarValues::Boolean; }
        action '进入驻车模式' : '功能步骤' { attribute '驻车状态' : ScalarValues::Boolean; }
        action '确认关机完成' : '功能步骤' { attribute '关机完成' : ScalarValues::Boolean; }
        succession '控制流 63' first '整车动力管理功能流程'::start then '整车动力管理功能流程'::'检测点火信号';
        succession '控制流 64' first '整车动力管理功能流程'::'检测点火信号' then '整车动力管理功能流程'::'检查电池状态';
        succession '控制流 65' first '整车动力管理功能流程'::'检查电池状态' then '整车动力管理功能流程'::'高压上电';
        succession '控制流 66' first '整车动力管理功能流程'::'高压上电' then '整车动力管理功能流程'::'系统自检';
        succession '控制流 67' first '整车动力管理功能流程'::'系统自检' then '整车动力管理功能流程'::'确认就绪状态';
        succession '控制流 68' first '整车动力管理功能流程'::'确认就绪状态' then '整车动力管理功能流程'::'解析驾驶意图';
        succession '控制流 69' first '整车动力管理功能流程'::'解析驾驶意图' then '整车动力管理功能流程'::'计算扭矩分配';
        succession '控制流 70' first '整车动力管理功能流程'::'计算扭矩分配' then '整车动力管理功能流程'::'管理动力输出';
        fork '正常驾驶分叉';
        succession '控制流 71' first '整车动力管理功能流程'::'管理动力输出' then '整车动力管理功能流程'::'正常驾驶分叉';
        succession '控制流 72' first '整车动力管理功能流程'::'正常驾驶分叉' then '整车动力管理功能流程'::'监控能量消耗';
        succession '控制流 73' first '整车动力管理功能流程'::'正常驾驶分叉' then '整车动力管理功能流程'::'控制热管理';
        succession '控制流 74' first '整车动力管理功能流程'::'正常驾驶分叉' then '整车动力管理功能流程'::'执行再生制动';
        join '正常驾驶汇合';
        succession '控制流 75' first '整车动力管理功能流程'::'监控能量消耗' then '整车动力管理功能流程'::'正常驾驶汇合';
        succession '控制流 76' first '整车动力管理功能流程'::'控制热管理' then '整车动力管理功能流程'::'正常驾驶汇合';
        succession '控制流 77' first '整车动力管理功能流程'::'执行再生制动' then '整车动力管理功能流程'::'正常驾驶汇合';
        succession '控制流 78' first '整车动力管理功能流程'::'正常驾驶汇合' then '整车动力管理功能流程'::'检测特殊工况';
        succession '控制流 79' first '整车动力管理功能流程'::'检测特殊工况' then '整车动力管理功能流程'::'调整动力策略';
        succession '控制流 80' first '整车动力管理功能流程'::'调整动力策略' then '整车动力管理功能流程'::'检测关机请求';
        succession '控制流 81' first '整车动力管理功能流程'::'检测关机请求' then '整车动力管理功能流程'::'保存车辆状态';
        succession '控制流 82' first '整车动力管理功能流程'::'保存车辆状态' then '整车动力管理功能流程'::'高压下电';
        succession '控制流 83' first '整车动力管理功能流程'::'高压下电' then '整车动力管理功能流程'::'进入驻车模式';
        succession '控制流 84' first '整车动力管理功能流程'::'进入驻车模式' then '整车动力管理功能流程'::'确认关机完成';
        succession '控制流 85' first '整车动力管理功能流程'::'确认关机完成' then '整车动力管理功能流程'::done;
        succession flow '对象流 22' from '整车动力管理功能流程'::'检测点火信号'.'点火状态' to '整车动力管理功能流程'::'检查电池状态'.'电池状态';
        succession flow '对象流 23' from '整车动力管理功能流程'::'检查电池状态'.'电池状态' to '整车动力管理功能流程'::'高压上电'.'高压状态';
        succession flow '对象流 24' from '整车动力管理功能流程'::'高压上电'.'高压状态' to '整车动力管理功能流程'::'系统自检'.'系统健康状态';
        succession flow '对象流 25' from '整车动力管理功能流程'::'系统自检'.'系统健康状态' to '整车动力管理功能流程'::'确认就绪状态'.'车辆就绪';
        succession flow '对象流 26' from '整车动力管理功能流程'::'确认就绪状态'.'车辆就绪' to '整车动力管理功能流程'::'解析驾驶意图'.'驾驶意图';
        succession flow '对象流 27' from '整车动力管理功能流程'::'解析驾驶意图'.'驾驶意图' to '整车动力管理功能流程'::'计算扭矩分配'.'驾驶意图';
        succession flow '对象流 28' from '整车动力管理功能流程'::'计算扭矩分配'.'扭矩指令' to '整车动力管理功能流程'::'管理动力输出'.'扭矩指令';
        succession flow '对象流 29' from '整车动力管理功能流程'::'管理动力输出'.'电机功率' to '整车动力管理功能流程'::'监控能量消耗'.'电机功率';
        succession flow '对象流 30' from '整车动力管理功能流程'::'监控能量消耗'.'能量状态' to '整车动力管理功能流程'::'控制热管理'.'能量状态';
        succession flow '对象流 31' from '整车动力管理功能流程'::'执行再生制动'.'回收能量' to '整车动力管理功能流程'::'监控能量消耗'.'能量状态';
        succession flow '对象流 32' from '整车动力管理功能流程'::'调整动力策略'.'调整后功率' to '整车动力管理功能流程'::'检测关机请求'.'关机信号';
        succession flow '对象流 33' from '整车动力管理功能流程'::'检测关机请求'.'关机信号' to '整车动力管理功能流程'::'保存车辆状态'.'车辆状态数据';
        succession flow '对象流 34' from '整车动力管理功能流程'::'保存车辆状态'.'车辆状态数据' to '整车动力管理功能流程'::'高压下电'.'高压状态';
        succession flow '对象流 35' from '整车动力管理功能流程'::'高压下电'.'高压状态' to '整车动力管理功能流程'::'进入驻车模式'.'驻车状态';
        succession flow '对象流 36' from '整车动力管理功能流程'::'进入驻车模式'.'驻车状态' to '整车动力管理功能流程'::'确认关机完成'.'关机完成';
    }
}

package '整车动力管理功能分析_结构' {
    doc /* 整车动力管理功能分析结构定义 */
    private import '整车动力管理功能分析'::'整车动力管理功能分析_活动'::*;
    part def '中央控制系统' {
        perform action '检测点火信号' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'检测点火信号';
        perform action '解析驾驶意图' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'解析驾驶意图';
        perform action '确认就绪状态' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'确认就绪状态';
        perform action '保存车辆状态' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'保存车辆状态';
        perform action '确认关机完成' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'确认关机完成';
    }
    part def '整车控制器' {
        perform action '系统自检' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'系统自检';
        perform action '计算扭矩分配' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'计算扭矩分配';
        perform action '激活雪地模式' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'激活雪地模式';
        perform action '激活运动模式' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'激活运动模式';
        perform action '激活经济模式' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'激活经济模式';
        perform action '进入驻车模式' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'进入驻车模式';
    }
    part def '电气系统' { perform action '检测关机请求' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'检测关机请求'; }
    part def '电池' {
        perform action '检查电池状态' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'检查电池状态';
        perform action '监控能量消耗' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'监控能量消耗';
    }
    part def '电机' { perform action '管理动力输出' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'管理动力输出'; }
    part def '动力总成' { perform action '调整动力策略' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'调整动力策略'; }
    part def '热管理' { perform action '控制热管理' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'控制热管理'; }
    part def '电驱电池系统' {
        perform action '高压上电' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'高压上电';
        perform action '执行再生制动' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'执行再生制动';
        perform action '高压下电' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'高压下电';
    }
    part def '计算模块' { perform action '检测特殊工况' : '整车动力管理功能分析'::'整车动力管理功能分析_活动'::'整车动力管理功能流程'::'检测特殊工况'; }
    part def '附件';
    part def '其它系统';
    part def '车辆模型';
}

package '整车动力管理_状态机' {
    doc /* 整车动力管理系统状态机行为分析视图 */
    private import ScalarValues::*;
    private import '整车动力管理功能分析'::'整车动力管理功能分析_结构'::*;

    attribute def '点火信号';
    attribute def '自检结果';
    attribute def '驾驶意图';
    attribute def '特殊工况标志';
    attribute def '车辆状态';
    attribute def '关机信号';
    attribute def '关机完成';
    attribute def '确认关机完成';

    port def '点火端口' { in '点火信号输入' : '点火信号'; }
    port def '自检端口' { in '自检结果输入' : '自检结果'; }
    port def '驾驶意图端口' { in '驾驶意图输入' : '驾驶意图'; }
    port def '模式控制端口' { in '特殊工况标志输入' : '特殊工况标志'; in '车辆状态输入' : '车辆状态'; }
    port def '关机端口' { in '关机信号输入' : '关机信号'; in '关机完成输入' : '关机完成'; in '确认关机完成输入' : '确认关机完成'; }

    part def '中央控制系统实例' : '中央控制系统' {
        port '点火端口' : '整车动力管理功能分析'::'整车动力管理_状态机'::'点火端口';
        port '自检端口' : '整车动力管理功能分析'::'整车动力管理_状态机'::'自检端口';
        port '驾驶意图端口' : '整车动力管理功能分析'::'整车动力管理_状态机'::'驾驶意图端口';
        port '模式控制端口' : '整车动力管理功能分析'::'整车动力管理_状态机'::'模式控制端口';
        port '关机端口' : '整车动力管理功能分析'::'整车动力管理_状态机'::'关机端口';

        attribute '电池状态' : Boolean;
        attribute '电池就绪' : Boolean;
        attribute '车辆就绪' : Boolean;
        attribute '高压状态' : Boolean;

        action '执行高压上电';
        action '确认就绪状态';
        action '执行高压下电';
        action '记录故障';
        action '解析驾驶意图';
        action '计算扭矩分配';
        action '激活雪地模式';
        action '激活运动模式';
        action '激活经济模式';
        action '恢复正常动力策略';
        action '保存车辆状态数据';
        action '进入驻车模式';
        action '完成系统断电';

        exhibit state '整车动力管理状态机' {
            doc /* 整车动力管理状态机：描述车辆从关机到运行再到关机的完整生命周期状态转换 */

            state '关机状态' { doc /* 关机状态：车辆完全断电，高压系统下电，处于驻车状态 */ }
            state '启动中' { doc /* 启动中：正在执行点火检测、电池检查、高压上电、系统自检流程 */ }
            state '就绪' { doc /* 就绪：系统自检通过，车辆就绪，等待驾驶意图输入 */ }
            state '运行中' { doc /* 运行中：正常行驶状态，执行扭矩分配、动力输出、能量监控 */ }
            state '雪地模式' { doc /* 雪地模式：特殊工况下的低附着力驾驶模式，动力输出受限 */ }
            state '运动模式' { doc /* 运动模式：特殊工况下的高性能驾驶模式，动力输出增强 */ }
            state '经济模式' { doc /* 经济模式：特殊工况下的节能驾驶模式，优先回收能量 */ }
            state '关机中' { doc /* 关机中：正在执行保存状态、高压下电、进入驻车流程 */ }
            state '驻车' { doc /* 驻车：已完成关机流程，车辆处于安全驻车状态 */ }

            transition '初始转换' first '关机状态' then '启动中';
            transition '关机状态 - 启动中' first '关机状态' accept '点火信号输入' : '点火信号' via '点火端口' if '电池状态' == true do '执行高压上电' then '启动中';
            transition '启动中 - 就绪' first '启动中' accept '自检结果输入' : '自检结果' via '自检端口' if '自检结果输入' == true and '电池就绪' == true do '确认就绪状态' then '就绪';
            transition '启动中 - 关机状态' first '启动中' accept '自检结果输入' : '自检结果' via '自检端口' if '自检结果输入' == false do '执行高压下电' then '关机状态';
            transition '就绪 - 运行中' first '就绪' accept '驾驶意图输入' : '驾驶意图' via '驾驶意图端口' if '驾驶意图输入' != null and '车辆就绪' == true do '解析驾驶意图' then '运行中';
            transition '运行中 - 雪地模式' first '运行中' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == true and '车辆状态' == snow do '激活雪地模式' then '雪地模式';
            transition '运行中 - 运动模式' first '运行中' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == true and '车辆状态' == sport do '激活运动模式' then '运动模式';
            transition '运行中 - 经济模式' first '运行中' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == true and '车辆状态' == eco do '激活经济模式' then '经济模式';
            transition '雪地模式 - 运行中' first '雪地模式' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == false do '恢复正常动力策略' then '运行中';
            transition '运动模式 - 运行中' first '运动模式' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == false do '恢复正常动力策略' then '运行中';
            transition '经济模式 - 运行中' first '经济模式' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == false do '恢复正常动力策略' then '运行中';
